int main(){int mode,fail;if(!(std::cin>>mode>>fail)||mode<0||mode>1||fail<0||fail>1){std::cout<<"invalid\n";return 0;}
 std::cin>>std::ws;if(!std::cin.eof()){std::cout<<"invalid\n";return 0;}
 academy::Board board;std::unique_ptr<academy::Policy> policy;
 if(mode==0)policy=std::make_unique<academy::Normal>();else policy=std::make_unique<academy::Urgent>();
 try{
  std::ifstream in{"data/tasks.txt"};int n;if(!(in>>n)||n<0||n>20)throw std::invalid_argument("input");
  std::vector<academy::Task> candidate;for(int i=0;i<n;++i){academy::Task t;if(!(in>>t.id>>t.minutes))throw std::invalid_argument("record");candidate.push_back(t);}
  in>>std::ws;if(!in.eof())throw std::invalid_argument("trailing");
  board.replace(std::move(candidate),fail==1);std::cout<<"accepted\n";
 }catch(const std::exception&){std::cout<<"rejected\n";}
 std::cout<<"tasks "<<board.tasks().size()<<" score "<<board.total(*policy)<<'\n';
 std::ofstream out{"board-report.txt"};if(!out){std::cout<<"export-failed\n";return 1;}
 academy::write_report(out,board,*policy);out.close();if(!out){std::cout<<"export-failed\n";return 1;}
}

