#ifndef NEXUS_M5_DOMAIN_HPP
#define NEXUS_M5_DOMAIN_HPP
#include <vector>
#include <concepts>
#include <ostream>
namespace academy {
struct Task {int id,minutes;};
template<std::integral T> bool bounded(T n,T lo,T hi){return lo<=n&&n<=hi;}
struct Policy {virtual int score(const Task&)const=0;virtual ~Policy()=default;};
struct Normal final:Policy {int score(const Task& t)const override{return t.minutes;}};
struct Urgent final:Policy {int score(const Task& t)const override{return 2*t.minutes;}};
class Board {
 std::vector<Task> tasks_{{1,10}};
public:
 void replace(std::vector<Task> candidate,bool fail);
 int total(const Policy& policy)const;
 const std::vector<Task>& tasks()const{return tasks_;}
};
void write_report(std::ostream&,const Board&,const Policy&);
}
#endif

