#include "domain.hpp"
#include <stdexcept>
namespace academy {
void Board::replace(std::vector<Task> candidate,bool fail){
 if(candidate.size()>20)throw std::invalid_argument("size");
 for(std::size_t i=0;i<candidate.size();++i){const auto& t=candidate[i];
  if(!bounded(t.id,1,100)||!bounded(t.minutes,0,100))throw std::invalid_argument("range");
  for(std::size_t j=0;j<i;++j)if(candidate[j].id==t.id)throw std::invalid_argument("duplicate");
 }
 if(fail)throw std::runtime_error("injected");
 tasks_.swap(candidate);
}
int Board::total(const Policy& policy)const{int n=0;for(const auto& t:tasks_)n+=policy.score(t);return n;}
}

